/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var ndarray = require( '@stdlib/ndarray/ctor' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var arraybuffer2ndarray = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof arraybuffer2ndarray, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns an ndarray', function test( t ) {
	var strides;
	var buffer;
	var offset;
	var dtype;
	var order;
	var shape;
	var arr;

	dtype = 'float64';
	buffer = new ArrayBuffer( 32 );
	shape = [ 2, 2 ];
	order = 'row-major';
	strides = [ 2, 1 ];
	offset = 0;

	arr = arraybuffer2ndarray( dtype, buffer, shape, strides, offset, order );

	t.strictEqual( instanceOf( arr, ndarray ), true, 'returns expected value' );
	t.end();
});

